export function projectLatLng(lat: number, lng: number): [number, number] {
  const r = Math.PI / 180
  const shift = lat < MAP.inset.lat && lng < MAP.inset.lng
  const x = MAP.tx + MAP.k * lng * r + (shift ? MAP.inset.dx : 0)
  const y = MAP.ty - MAP.k * Math.log(Math.tan(Math.PI / 4 + (lat * r) / 2)) + (shift ? MAP.inset.dy : 0)
  // Rounded so server and browser agree (their Math.log/tan can differ in the last bits).
  return [Math.round(x * 100) / 100, Math.round(y * 100) / 100]
}
